<script setup lang="ts">
/**
 * Page-level list of form errors after a failed submit (`design/components/error-summary.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/error-summary.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, useTemplateRef } from 'vue'

import { Icon, agentMember, chooseListItem, listItems } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/error-summary.module.css'

export interface ErrorSummaryError {
  label: string
  fieldId: string
}

export interface ErrorSummaryProps {
  /**
   * Errors in form order, the navigation order (Stat's rule); an empty list renders nothing.
   */
  errors: ErrorSummaryError[]
  /**
   * Text from the app ("The ticket can't be raised yet"); the vocabulary writes no error copy.
   */
  title: string
}

defineOptions({ name: 'ErrorSummary', inheritAttrs: false })

defineProps<ErrorSummaryProps>()
const list = useTemplateRef<HTMLElement>('list')
const root = useTemplateRef<HTMLElement>('root')
const follow = computed(() => (event: MouseEvent, fieldId: string) => {
  const control = document.getElementById(fieldId)
  if (control === null) return
  event.preventDefault()
  control.focus()
  control.scrollIntoView({ block: 'nearest' })
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ErrorSummary',
    element: () => root.value,
    state: () => ({ items: listItems(list.value, styles.link) }),
    actions: {
      choose: { argument: 'id', run: (value) => chooseListItem(list.value, styles.link, value) },
    },
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <div
    v-if="errors.length > 0"
    ref="root"
    :class="styles.root"
    role="alert"
    data-member="error-summary"
  >
    <!-- glyph -->
    <span :class="styles.glyph">
      <Icon name="error" size="md" />
    </span>
    <!-- body -->
    <div :class="styles.body">
      <!-- title -->
      <p :class="styles.title">
        {{ title }}
      </p>
      <!-- list -->
      <ul ref="list" :class="styles.list">
        <template v-for="(error, at) in errors" :key="`${at}-${error.fieldId}`">
          <li>
            <!-- entry -->
            <a
              :class="styles.link"
              :href="`#${error.fieldId}`"
              @click="follow($event, error.fieldId)"
            >
              {{ error.label }}
            </a>
          </li>
        </template>
      </ul>
    </div>
  </div>
</template>
